// 023 T149 — a FROZEN copy of how the installed v1.0.1 app reads pulled
// money_transaction and finance_entry rows. Do not edit this file to follow
// current code: it exists so the compatibility test keeps running v1.0.1
// semantics even after the live mappers or `SyncWire` change.
//
// Sources (v1.0.1 = commit c86e2df, "chore(release): v1.0.1"):
//   git show c86e2df:lib/features/transactions/data/sync/money_transaction_sync_mapper.dart
//     (class constants :13-15, fromWire :45-83)
//   git show c86e2df:lib/features/finance/data/sync/finance_entry_sync_mapper.dart
//     (class constant :14, fromWire :37-60)
//   git show c86e2df:lib/core/sync/sync_mapper_registry.dart
//     (SyncWire helpers that those bodies call: parseMoney, parseInstant,
//     parseInstantOrNull, parseFirstInstant, string, stringOrNull, boolean,
//     oneOf, _bad)
//
// The only edits to the copied text: `SyncWire.` became `_V101Wire.`, the
// classes no longer extend `SyncMapper` (only `fromWire` is frozen, so the
// `@override` annotations are gone), and the class names carry a `V101`
// prefix. The Drift companions are generated from the CURRENT schema; every
// column added since v1.0.1 is optional, so the frozen `.insert(...)` calls
// compile unchanged and leave the new columns absent, as v1.0.1 would.
import 'package:daftary/core/database/app_database.dart';

/// v1.0.1 `MoneyTransactionSyncMapper.fromWire`, frozen.
class V101MoneyTransactionSyncMapper {
  const V101MoneyTransactionSyncMapper();

  static const directions = {'given', 'received'};
  static const kinds = {'initialExchange', 'repayment', 'occasionContribution'};
  static const sources = {'manual', 'ocr'};

  MoneyTransactionsCompanion fromWire(
    Map<String, Object?> json, {
    MoneyTransaction? existingLocal,
  }) => MoneyTransactionsCompanion.insert(
    id: _V101Wire.string(json, 'id'),
    idempotencyKey: _V101Wire.string(json, 'idempotency_key'),
    personId: _V101Wire.string(json, 'person_id'),
    amountMinorUnits: _V101Wire.parseMoney(
      json['amount_minor'],
      'amount_minor',
    ),
    currencyCode: Value(_V101Wire.string(json, 'currency_code')),
    direction: _V101Wire.oneOf(json, 'direction', directions),
    kind: _V101Wire.oneOf(json, 'kind', kinds),
    date: _V101Wire.parseInstant(json['occurred_at'], 'occurred_at'),
    note: Value(_V101Wire.stringOrNull(json, 'note')),
    occasionId: Value(_V101Wire.stringOrNull(json, 'occasion_id')),
    // A row the server stored before 022 has none of these: it was an
    // ordinary, counting, hand-typed transaction.
    countsTowardBalance: Value(
      json['counts_toward_balance'] == null
          ? true
          : _V101Wire.boolean(json, 'counts_toward_balance'),
    ),
    source: Value(
      json['source'] == null
          ? 'manual'
          : _V101Wire.oneOf(json, 'source', sources),
    ),
    ocrScanId: Value(_V101Wire.stringOrNull(json, 'ocr_scan_id')),
    createdAt: _V101Wire.parseFirstInstant(json, const [
      'client_created_at',
      'server_created_at',
    ]),
    editedAt: Value(
      _V101Wire.parseInstantOrNull(json['edited_at'], 'edited_at'),
    ),
    deletedAt: Value(
      _V101Wire.parseInstantOrNull(json['deleted_at'], 'deleted_at'),
    ),
  );
}

/// v1.0.1 `FinanceEntrySyncMapper.fromWire`, frozen.
class V101FinanceEntrySyncMapper {
  const V101FinanceEntrySyncMapper();

  static const types = {'income', 'expense'};

  FinanceEntriesCompanion fromWire(
    Map<String, Object?> json, {
    FinanceEntry? existingLocal,
  }) => FinanceEntriesCompanion.insert(
    id: _V101Wire.string(json, 'id'),
    idempotencyKey: _V101Wire.string(json, 'idempotency_key'),
    categoryId: _V101Wire.string(json, 'category_id'),
    type: _V101Wire.oneOf(json, 'type', types),
    amountMinorUnits: _V101Wire.parseMoney(
      json['amount_minor'],
      'amount_minor',
    ),
    currencyCode: Value(_V101Wire.string(json, 'currency_code')),
    date: _V101Wire.parseInstant(json['occurred_at'], 'occurred_at'),
    note: Value(_V101Wire.stringOrNull(json, 'note')),
    createdAt: _V101Wire.parseFirstInstant(json, const [
      'client_created_at',
      'server_created_at',
    ]),
    editedAt: Value(
      _V101Wire.parseInstantOrNull(json['edited_at'], 'edited_at'),
    ),
    deletedAt: Value(
      _V101Wire.parseInstantOrNull(json['deleted_at'], 'deleted_at'),
    ),
  );
}

/// The v1.0.1 `SyncWire` decoders the two bodies above call, frozen.
abstract final class _V101Wire {
  static int parseMoney(Object? value, String field) => switch (value) {
    final String s => int.tryParse(s) ?? _bad(field, value),
    final int i => i,
    _ => _bad(field, value),
  };

  static int parseInstant(Object? value, String field) {
    if (value is! String) return _bad(field, value);
    final parsed = DateTime.tryParse(value);
    if (parsed == null) return _bad(field, value);
    return parsed.millisecondsSinceEpoch;
  }

  static int? parseInstantOrNull(Object? value, String field) =>
      value == null ? null : parseInstant(value, field);

  static int parseFirstInstant(Map<String, Object?> json, List<String> fields) {
    for (final field in fields) {
      final value = json[field];
      if (value != null) return parseInstant(value, field);
    }
    return _bad(fields.join('|'), null);
  }

  static String string(Map<String, Object?> json, String field) {
    final value = json[field];
    return value is String ? value : _bad(field, value);
  }

  static String? stringOrNull(Map<String, Object?> json, String field) {
    final value = json[field];
    if (value == null) return null;
    return value is String ? value : _bad(field, value);
  }

  static bool boolean(Map<String, Object?> json, String field) {
    final value = json[field];
    return value is bool ? value : _bad(field, value);
  }

  static String oneOf(
    Map<String, Object?> json,
    String field,
    Set<String> allowed,
  ) {
    final value = string(json, field);
    return allowed.contains(value) ? value : _bad(field, value);
  }

  static Never _bad(String field, Object? value) => throw FormatException(
    'Invalid wire value for "$field"',
    value?.runtimeType.toString(),
  );
}
